import '../domain/entities/catalog_definition.dart';

/// Второй уровень структуры каталогов.
///
/// Формат: каталог -> id первого уровня -> названия второго уровня.
class CatalogSecondLevelDefaults {
  static List<CatalogSectionDefinition> apply(String catalogId, List<CatalogSectionDefinition> sections) {
    final definitions = _definitions[catalogId];
    if (definitions == null) return sections;

    return sections.map((section) {
      final raw = definitions[section.id];
      if (raw == null) return section;
      final names = raw.split('|');
      return CatalogSectionDefinition(
        id: section.id,
        name: section.name,
        children: names.map((name) => CatalogSectionDefinition(id: _id(name), name: name)).toList(growable: false),
      );
    }).toList(growable: false);
  }

